    Button pad(String name,int id){Button p=ui.button(name,v->{});final float[] start={0};p.setOnTouchListener((v,e)->{switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:start[0]=e.getY();heldPads.add(p);p.setPressed(true);p.getParent().requestDisallowInterceptTouchEvent(true);Native.event(Native.PERFORM,id,1);return true;case MotionEvent.ACTION_MOVE:if(Math.abs(e.getY()-start[0])>ui.dp(18)){heldPads.remove(p);p.setPressed(false);Native.event(Native.PERFORM,id,0);p.getParent().requestDisallowInterceptTouchEvent(false);return false;}return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:heldPads.remove(p);p.setPressed(false);p.getParent().requestDisallowInterceptTouchEvent(false);Native.event(Native.PERFORM,id,0);return true;}return true;});p.setTag(id);return p;}
